const DIFF={easy:{xp:5,label:'Easy',c:'#22c55e'},medium:{xp:10,label:'Medium',c:'#f59e0b'},hard:{xp:20,label:'Hard',c:'#ef4444'}};
const GOAL_LEVELS=[[0,'Beginner','🌱'],[150,'Consistent','⚡'],[400,'Advanced','🚀'],[800,'Elite','👑']];
function mlogs(){try{return JSON.parse(localStorage.getItem('goalify_mlog_'+uid()))||{};}catch(e){return{};}}
function setMlogs(o){localStorage.setItem('goalify_mlog_'+uid(),JSON.stringify(o));}
function missionLog(id){return mlogs()[id]||{};}
function isDoneToday(id){return !!missionLog(id)[todayISO()];}
function weekStartISO(d=new Date()){const x=new Date(d);x.setDate(x.getDate()-((x.getDay()+6)%7));return x.toISOString().slice(0,10);} // Monday
function doneThisWeek(id){const ws=weekStartISO(),log=missionLog(id);return Object.keys(log).filter(k=>k>=ws).length;}
function missionStreak(id){const log=missionLog(id);let n=0,d=new Date();if(!log[todayISO()])d.setDate(d.getDate()-1);for(;;){const k=d.toISOString().slice(0,10);if(log[k]){n++;d.setDate(d.getDate()-1);}else break;}return n;}
function missionBest(id){const days=Object.keys(missionLog(id)).sort();let best=0,run=0,prev=null;days.forEach(k=>{run=prev&&(new Date(k)-new Date(prev))/864e5===1?run+1:1;best=Math.max(best,run);prev=k;});return best;}
function streakHealth(n){if(n>=7)return{label:'Strong',c:'#22c55e',e:'🔥'};if(n>=3)return{label:'Stable',c:'#3b82f6',e:'💪'};if(n>=1)return{label:'Weak',c:'#f59e0b',e:'⚠️'};return{label:'Critical',c:'#ef4444',e:'❗'};}
function allMissions(){return GOALS.flatMap(g=>(g.missions||[]).map(m=>({...m,goal:g})));}
function missionTarget(m){return m.cadence==='daily'?(m.perWeek||5):(m.perWeek||1);}
function missionDueToday(m){if(m.status!=='active')return false;return m.cadence==='daily'?!isDoneToday(m.id):doneThisWeek(m.id)<missionTarget(m);}
function checkInMission(id){const o=mlogs();o[id]=o[id]||{};o[id][todayISO()]=true;setMlogs(o);}
function uncheckMission(id){const o=mlogs();if(o[id])delete o[id][todayISO()];setMlogs(o);}

// ============================================================
// GOALCOINS — MVP economy (append-only ledger in localStorage; same
// function shapes as the future Supabase RPCs so the swap is trivial).
// Server-authoritative caps/idempotency are mirrored here client-side.
// ============================================================
const COIN_EARN={checkin:5,streak7:25,goal_complete:100,recap:20};
const COIN_DAILY_CAP=120;
function coinKey(){return 'goalify_coins_'+uid();}
function coinLedger(){try{return JSON.parse(localStorage.getItem(coinKey()))||[];}catch(e){return [];}}
function setCoinLedger(l){localStorage.setItem(coinKey(),JSON.stringify(l));}
function coinBalance(){return coinLedger().reduce((s,r)=>s+(r.delta||0),0);}
function coinEarnedToday(){const t=todayISO();return coinLedger().filter(r=>r.delta>0&&(r.at||'').slice(0,10)===t).reduce((s,r)=>s+r.delta,0);}
function coinHas(reason,ref){return coinLedger().some(r=>r.reason===reason&&r.ref===ref);}
// EARN — whitelisted amounts, once-per-ref idempotency, daily cap. Returns coins actually credited.
function coinMultiplier(){return ME?.plan==='premium'||ME?.plan==='business'?2:ME?.plan==='pro'?1.5:1;}
function creditCoins(reason,ref){
  const base=COIN_EARN[reason];if(!base)return 0;
  if(ref&&coinHas(reason,ref))return 0;                 // idempotent
  let amt=Math.round(base*coinMultiplier());            // tier ×1 / ×1.5 / ×2
  if(coinEarnedToday()+amt>COIN_DAILY_CAP)return 0;      // daily cap
  const wcap=coinWeeklyCap();const wk=coinEarnedThisWeek();
  if(wk>=wcap)return 0;                                  // weekly cap (Free = 80)
  if(wk+amt>wcap)amt=wcap-wk;                            // partial credit up to cap
  if(amt<=0)return 0;
  const l=coinLedger();l.push({delta:amt,reason,ref:ref||null,at:new Date().toISOString(),sync:0});setCoinLedger(l);
  refreshCoinPills();syncCoinLedger();
  return amt;
}
// SPEND — atomic balance check. Returns true on success.
function spendCoins(reason,item,cost){
  if(coinBalance()<cost)return false;
  const l=coinLedger();l.push({delta:-cost,reason,ref:item,at:new Date().toISOString(),sync:0});setCoinLedger(l);
  refreshCoinPills();syncCoinLedger();
  return true;
}
// Instantly repaint every visible balance (topbar, sidebar, store, profile) —
// no render() needed, so an earn can never leave a stale pill on screen.
function refreshCoinPills(){const b=coinBalance().toLocaleString('en-IE');document.querySelectorAll('.coin-bal').forEach(el=>{el.textContent=b;});}
// Durable sync — localStorage is the instant cache, Supabase coin_ledger is the
// source of truth (credit_coins/spend_coins RPCs enforce caps server-side).
// Entries carry sync:0 until accepted; legacy entries (no flag) are replayed
// only when idempotent (positive, whitelisted, with ref), then everything is
// reconciled against the server balance so all devices agree.
let _coinSyncBusy=false;
async function syncCoinLedger(){
  if(DEMO_MODE||!SESSION||_coinSyncBusy)return;
  _coinSyncBusy=true;
  try{
    const l=coinLedger();let dirty=false;
    for(const r of l){
      if(r.sync===1)continue;
      const legacy=!('sync' in r);
      const bonus=r.reason==='first_analysis';
      const earnable=r.delta>0&&r.ref&&(COIN_EARN[r.reason]||bonus);
      if(legacy&&!earnable){r.sync=1;dirty=true;continue;}          // never replay legacy spends
      let res;
      if(r.delta>0){
        if(!earnable){r.sync=1;dirty=true;continue;}
        res=await sb.rpc('credit_coins',{p_reason:r.reason,p_ref:r.ref,p_amount:bonus?100:COIN_EARN[r.reason]});
      }else{
        res=await sb.rpc('spend_coins',{p_reason:r.reason,p_item:r.ref,p_cost:-r.delta});
      }
      if(!res.error){r.sync=1;dirty=true;}
      else if(!/fetch|network/i.test(res.error.message||'')){r.sync=1;dirty=true;} // server rejected (cap/idempotent/locked) — settled
      // network failure: leave unsynced, retry on next sync
    }
    if(dirty)setCoinLedger(l);
    // reconcile: server balance wins once everything sent is settled
    if(l.every(r=>r.sync===1||!('sync' in r))){
      const {data}=await sb.from('coin_balance').select('balance').eq('user_id',SESSION.user.id).maybeSingle();
      if(data&&typeof data.balance==='number'){
        const local=coinBalance();
        if(data.balance!==local){
          const l2=coinLedger();l2.push({delta:data.balance-local,reason:'sync',ref:null,at:new Date().toISOString(),sync:1});setCoinLedger(l2);
          refreshCoinPills();
        }
      }
    }
  }catch(e){/* offline — retry next time */}
  finally{_coinSyncBusy=false;}
}
const COIN_REASON_LABEL={checkin:'Habit check-in',streak7:'7-day streak',goal_complete:'Goal completed',recap:'Weekly recap',cosmetic:'Store purchase'};
// fly-to-wallet — coins are appended to <body> so they survive a render()
// (earn events re-render #root); the count-up runs on the fresh pill after.
function visibleCoinPill(){return [...document.querySelectorAll('.coin-pill')].find(p=>p.getBoundingClientRect().width>0);}
function flyCoins(fromEl){
  const pill=visibleCoinPill();
  const reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion:reduce)').matches;
  if(!pill||!fromEl||reduce)return;
  const pr=pill.getBoundingClientRect(),fr=fromEl.getBoundingClientRect();
  const tx=pr.left+pr.width/2,ty=pr.top+pr.height/2,sx=fr.left+fr.width/2,sy=fr.top+fr.height/2;
  for(let i=0;i<5;i++){
    const g=document.createElement('div');g.className='coin-fly';g.textContent='⊙';
    g.style.left=(sx-10)+'px';g.style.top=(sy-10)+'px';document.body.appendChild(g);
    const a=g.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${(tx-sx).toFixed(1)}px,${(ty-sy).toFixed(1)}px) scale(.4)`,opacity:0}],{duration:460,delay:i*55,easing:'cubic-bezier(.22,1,.36,1)',fill:'forwards'});
    a.onfinish=()=>g.remove();
  }
}
// bump + count-up on the (post-render) visible pill
function pulseCoinPill(from,to){
  const pill=visibleCoinPill();const bals=[...document.querySelectorAll('.coin-bal')];if(!bals.length)return;
  if(pill){pill.classList.remove('coinPill-bump');void pill.offsetWidth;pill.classList.add('coinPill-bump');}
  const reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion:reduce)').matches;
  const setAll=v=>bals.forEach(b=>b.textContent=Math.round(v).toLocaleString('en-IE'));
  if(reduce){setAll(to);return;}
  const t0=performance.now(),dur=520;(function f(now){const k=Math.min(1,(now-t0)/dur),e=1-Math.pow(1-k,3);setAll(from+(to-from)*e);if(k<1)requestAnimationFrame(f);})(performance.now());
}
// credit + fly (before the caller's render). The count-up is replayed on the
// freshly-rendered pill via the _coinPulse hook consumed at the end of render().
let _coinPulse=null;
function coinEarn(reason,ref,fromEl){
  const before=coinBalance();const got=creditCoins(reason,ref);
  if(got>0){flyCoins(fromEl);_coinPulse={from:before,to:before+got};}
  return got;
}
