  nightlife:{Kosovo:15,Albania:15,'North Macedonia':16,Serbia:20,Greece:30,Spain:35,Italy:38,France:45,Germany:42,Netherlands:45,'United Kingdom':50,Ireland:55,'United States':58,Switzerland:75,Other:38},
