document.addEventListener('submit',async(e)=>{
  const f=e.target; e.preventDefault();
  try{
    if(f.id==='signupForm'){
      const fd=new FormData(f);
      if(fd.get('password')!==fd.get('confirm'))return toast('Passwords do not match','err');
      const {score}=pwStrength(fd.get('password'));
      if(score<3)return toast('Password too weak — needs 8+ chars, a number, and a letter','err');
      if(!fd.get('accept_privacy'))return toast('Please accept the Privacy Policy & Terms to continue','err');
      const newsOptIn=!!fd.get('accept_news');
      // referral: stash the friend's code so the rewards backend can credit both sides
      const refCode=(fd.get('referral_code')||'').toString().trim().toUpperCase();
      if(refCode)localStorage.setItem('goalify_ref_entered',refCode);
      const bd=fd.get('birthdate')||'',ctry=fd.get('country')||'',lng=fd.get('language')||'en';
      if(lng){localStorage.setItem('goalify_lang',lng);}
      // seed onboarding state so the quiz can skip language & country (already collected here)
      if(typeof QA!=='undefined'&&QA){QA.lang=lng;QA.country=ctry||QA.country;}
      if(DEMO_MODE){Object.assign(DEMO_ME,{first_name:fd.get('first_name')||'',last_name:fd.get('last_name')||'',email:fd.get('email')||DEMO_ME.email,birthdate:bd,country:ctry||DEMO_ME.country,language:lng,onboarded:false});toast('Welcome to Goalify! 🎉');location.hash='#quiz';return;}
      const btn=$('#signupBtn');btn.disabled=true;btn.textContent='Creating…';
      const email=fd.get('email');
      const redirectTo=location.protocol==='file:'?undefined:location.origin+(location.pathname==='/'?'':location.pathname);
      const {data,error}=await sb.auth.signUp({email,password:fd.get('password'),options:{emailRedirectTo:redirectTo,data:{first_name:fd.get('first_name'),last_name:fd.get('last_name'),dob:bd,country:ctry,language:lng,marketing_opt_in:newsOptIn,privacy_accepted_at:new Date().toISOString()}}});
      btn.disabled=false;btn.textContent='Create account';
      if(error)return toast(error.message,'err');
      if(data.session){location.hash='#quiz';}
      else{localStorage.setItem('goalify_pending_email',email);toast('We sent an 8-digit code to your email 📨');location.hash='#verify';}
    }
    else if(f.id==='otpForm'){
      if(window._verifying)return;                 // single request — no duplicate submits
      const email=localStorage.getItem('goalify_pending_email')||'';
      const code=($('#otpInput')?.value||'').replace(/[^0-9]/g,'');
      const msg=$('#otpMsg'),btn=$('#otpBtn');
      const setMsg=(t,ok)=>{if(msg){msg.style.color=ok?'#34d399':'#f87171';msg.textContent=t;}};
      const reset=()=>{window._verifying=false;if(btn){btn.disabled=false;btn.textContent='Verify & continue';}};
      if(!email){setMsg('Session expired — please sign up again.');return;}
      if(!/^\d{8}$/.test(code)){setMsg('Enter the 8-digit code.');return;}
      window._verifying=true;if(btn){btn.disabled=true;btn.textContent='Verifying…';}
      const TIMEOUT=20000; // real network-timeout guard only (lock is disabled so this rarely fires)
      const race=(p)=>Promise.race([p,new Promise((_,rej)=>setTimeout(()=>rej(new Error('__timeout__')),TIMEOUT))]);
      try{
        // signUp() confirmation OTP is type 'signup'. Supabase returns the SAME "invalid/expired"
        // message for a wrong type, so if 'signup' fails we try the generic 'email' type once.
        let {data,error}=await race(sb.auth.verifyOtp({email,token:code,type:'signup'}));
        if(error){
          console.error('[Goalify] verifyOtp(type:signup) error:',{message:error.message,status:error.status,name:error.name,code:error.code,error});
          const r2=await race(sb.auth.verifyOtp({email,token:code,type:'email'}));
          data=r2.data;error=r2.error;
          if(error)console.error('[Goalify] verifyOtp(type:email) error:',{message:error.message,status:error.status,name:error.name,code:error.code,error});
        }
        if(error){ setMsg(error.message||'Verification failed'); reset(); return; } // REAL Supabase message
        setMsg('✓ Verified! Signing you in…',true);
        localStorage.removeItem('goalify_pending_email');
        if(_otpTimer){clearInterval(_otpTimer);_otpTimer=null;}_otpCooldown=0;
        // session is created by verifyOtp; confirm/refresh it before redirecting
        SESSION=(data&&data.session)||null;
        if(!SESSION){try{const {data:s}=await race(sb.auth.getSession());SESSION=(s&&s.session)||null;}catch(e){console.error('[Goalify] getSession after verify:',e);}}
        if(SESSION){try{await loadProfile();}catch(e){console.error('[Goalify] loadProfile after verify:',e);}}
        window._verifying=false;
        location.hash = isOnboarded() ? '#app/dashboard' : '#quiz';
      }catch(err){
        if(err&&err.message==='__timeout__'){console.error('[Goalify] verifyOtp timed out after',TIMEOUT,'ms');setMsg('The request timed out — check your connection and try again.');}
        else{console.error('[Goalify] verifyOtp exception:',err);setMsg((err&&err.message)||'Verification failed — please try again');}
        reset();
      }
    }
    else if(f.id==='loginForm'){
      const fd=new FormData(f);
      if(DEMO_MODE){toast('Welcome back! 👋');location.hash=DEMO_ME.onboarded?'#app/dashboard':'#quiz';return;}
      if(window._loginInFlight)return; // ignore double-taps while a request is already resolving
      if(fd.get('remember'))localStorage.setItem(REMEMBER,'1');else localStorage.removeItem(REMEMBER);
      const btn=$('#loginBtn');btn.disabled=true;btn.textContent='Logging in…';
      const fail=(m)=>{window._loginInFlight=false;btn.disabled=false;btn.textContent='Log in';toast(m||'Login failed — please try again','err');};
      window._loginInFlight=true;
      // Self-contained login: don't wait on onAuthStateChange (which can lag/hang on slow networks).
      // 20s (was 12s — too aggressive, tripped on ordinary mobile latency and a cold/paused Supabase
      // project). A race can't cancel the underlying request — a slow-but-working connection keeps
      // trying in the background even after our timeout fires. So on timeout we don't give up
      // instantly: we poll for up to ~6 more seconds for the session to land before telling the
      // user it failed. This is what "network is slow" should actually mean — wait longer, not error faster.
      try{
        let res;
        try{
          res=await Promise.race([
            sb.auth.signInWithPassword({email:fd.get('email'),password:fd.get('password')}),
            new Promise((_,rej)=>setTimeout(()=>rej(new Error('__timeout__')),20000))
          ]);
        }catch(raceErr){
          if(raceErr&&raceErr.message==='__timeout__'){
            let landed=null;
            for(let i=0;i<4&&!landed;i++){
              await new Promise(r=>setTimeout(r,1500));
              const {data}=await sb.auth.getSession();
              if(data&&data.session)landed=data.session;
            }
            if(landed){res={data:{session:landed},error:null};} // the slow request actually succeeded — don't lie to the user
            else throw raceErr;
          } else throw raceErr;
        }
        if(res&&res.error){return fail(res.error.message);}
        SESSION=(res&&res.data&&res.data.session)||(await sb.auth.getSession()).data.session;
        if(!SESSION){return fail('Incorrect email or password');}
        window._loginInFlight=false;
        btn.textContent='Success ✓';
        try{await Promise.race([loadProfile(),new Promise(r=>setTimeout(r,6000))]);}catch(e){}
        toast('Welcome back! 👋');
        location.hash = isOnboarded() ? '#app/dashboard' : '#quiz';
      }catch(e){
        fail(e&&e.message==='__timeout__' ? 'Network is slow — please try again' : (e&&e.message));
      }
    }
    else if(f.id==='forgotForm'){const fd=new FormData(f);if(DEMO_MODE){toast('Reset link sent — check your email (demo).');location.hash='#login';return;}const {error}=await sb.auth.resetPasswordForEmail(fd.get('email'),{redirectTo:location.origin+location.pathname+'#reset'});if(error)return toast(error.message,'err');toast('Reset link sent — check your email.');}
    else if(f.id==='resetForm'){const fd=new FormData(f);if(fd.get('password')!==fd.get('confirm'))return toast('Passwords do not match','err');const {error}=await sb.auth.updateUser({password:fd.get('password')});if(error)return toast(error.message,'err');toast('Password updated');location.hash='#app/dashboard';}
    else if(f.id==='expForm'){const fd=new FormData(f);if(DEMO_MODE){const exp={id:'e'+Date.now(),user_id:'demo',amount:+fd.get('amount'),category:fd.get('category'),merchant:fd.get('merchant'),spent_at:fd.get('date')||todayISO()};DEMO_EXPENSES.unshift(exp);toast('Expense added (demo)');render();}else{await sb.from('expenses').insert({user_id:SESSION.user.id,amount:+fd.get('amount'),category:fd.get('category'),merchant:fd.get('merchant'),spent_at:fd.get('date')||todayISO()});toast('Expense added');render();}}
    else if(f.id==='profForm'){const fd=new FormData(f);if(DEMO_MODE){Object.assign(DEMO_ME,{first_name:fd.get('first_name'),last_name:fd.get('last_name'),username:fd.get('username'),country:fd.get('country'),bio:fd.get('bio'),monthly_income:+fd.get('monthly_income')||0,currency:fd.get('currency')});toast('Profile saved (demo)');render();}else{await sb.from('profiles').update({first_name:fd.get('first_name'),last_name:fd.get('last_name'),username:fd.get('username'),country:fd.get('country'),bio:fd.get('bio'),monthly_income:+fd.get('monthly_income')||0,currency:fd.get('currency')}).eq('id',SESSION.user.id);await loadProfile();toast('Profile saved');render();}}
    else if(f.id==='pwForm'){if(DEMO_MODE){toast('Password change is not available in demo mode','err');return;}const fd=new FormData(f);if(!fd.get('password'))return;if(fd.get('password')!==fd.get('confirm'))return toast('Passwords do not match','err');const {error}=await sb.auth.updateUser({password:fd.get('password')});if(error)return toast(error.message,'err');toast('Password updated');f.reset();}
    else if(f.id==='chatForm'){const inp=$('#chatInput');const v=inp.value.trim();if(v){inp.value='';sendChat(v);}}
    else if(f.id==='svForm'){
      if(DEMO_MODE){toast('Student verification is not available in demo mode','err');return;}
      const sbtn=f.querySelector('button.btn-primary');
      if(sbtn){sbtn.disabled=true;sbtn.textContent='Uploading…';}
      const fail=(m)=>{if(sbtn){sbtn.disabled=false;sbtn.textContent='Submit for verification →';}toast(m,'err');};
      const fd=new FormData(f);const file=fd.get('document');let docUrl=null;
      if(file&&file.size){const path=SESSION.user.id+'/'+Date.now()+'_'+file.name.replace(/[^\w.]/g,'_');const {error:upErr}=await sb.storage.from('documents').upload(path,file);if(!upErr)docUrl=path;}
      if(sbtn)sbtn.textContent='Submitting…';
      const {error}=await sb.from('student_verifications').insert({user_id:SESSION.user.id,university:fd.get('university'),student_email:fd.get('student_email'),document_url:docUrl});
      if(error)return fail(error.message);
      toast('Submitted! An admin will review it. 🎓');render();
    }
  }catch(err){toast(err.message||'Error','err');}
});

