sb.auth.onAuthStateChange(async (event,session)=>{
  if(DEMO_MODE) return; // demo mode ignores all real auth events
  SESSION=session; ME=null;
  if(event==='PASSWORD_RECOVERY'){location.hash='#reset';return;}
  if(event==='SIGNED_IN'){ await loadProfile(); location.hash = isOnboarded() ? '#app/dashboard' : '#quiz'; return; }
  if(event==='SIGNED_OUT'){ localStorage.removeItem('goalify_onboarded'); render(); return; }
  render();
});
// path->hash bridge: vercel rewrites serve index.html for every path, so friendly
// URLs like /login, /signup, /dashboard work by translating into hash routes.
function pathToHash(path){const seg=(path||'').replace(/^\/+|\/+$/g,'');if(!seg||seg==='index.html')return '';
  const known=['login','signup','forgot','reset','verify','quiz','privacy'];
  if(known.indexOf(seg)>-1)return '#'+seg;
  if(seg.indexOf('join/')===0)return '#'+seg;
  if(seg==='dashboard'||seg==='app')return '#app/dashboard';
  if(seg.indexOf('app/')===0)return '#'+seg;
  return '';}
window.pathToHash=pathToHash;try{const _h=pathToHash(location.pathname);if(_h){history.replaceState(null,'',location.origin+'/');location.hash=_h;}}catch(e){}
window.addEventListener('hashchange',render);
loadTheme();
(async()=>{
  if(DEMO_MODE){
    // Wipe any real Supabase session from storage so the SDK stops making auth/DB calls
    const key='sb-jcskgasaocfueneyahrk-auth-token';
    localStorage.removeItem(key); sessionStorage.removeItem(key);
    localStorage.removeItem(REMEMBER);
    SESSION=null; ME=DEMO_ME;
    // restore saved avatar; seed a streak so badges feel alive in the demo
    ME.avatar_url=localStorage.getItem('goalify_avatar_demo')||null;
    seedDemoMissions();
    if(!localStorage.getItem('goalify_bg'))localStorage.setItem('goalify_bg','aurora');
    applyTheme(localStorage.getItem('goalify_theme')||ME.theme||'dark',localStorage.getItem('goalify_color')||ME.theme_color||'blue');applyBg(localStorage.getItem('goalify_bg'));
    render(); return;
  }
  // Resilient startup: never let a slow/blocked Supabase call leave the app on "Loading…".
  // Race every auth/profile call against a timeout, and always render at the end.
  const withTimeout=(p,ms)=>Promise.race([Promise.resolve(p).catch(()=>null),new Promise(r=>setTimeout(()=>r(null),ms))]);
  try{
    const res=await withTimeout(sb.auth.getSession(),4000);
    SESSION=(res&&res.data&&res.data.session)||null;
    if(SESSION) await withTimeout(loadProfile(),4000);
  }catch(e){ SESSION=null; }
  render();
})();
