function groupDetailView(g){
  const M='style="color:var(--muted)"';
  const p=Math.min(100,Math.round((g.saved_amount/g.target_amount)*100||0));
  const mem=g._members||[],con=g._contribs||[];
  const canContribute=['owner','admin','contributor'].includes(g.role);
  const days=g.target_date?Math.ceil((new Date(g.target_date)-Date.now())/864e5):null;
  const avatars=mem.slice(0,6).map(m=>`<span class="flex h-8 w-8 items-center justify-center rounded-full text-white text-xs font-bold" style="background:linear-gradient(135deg,var(--accent1),var(--accent2));margin-left:-6px;border:2px solid var(--bg)" title="${esc(m.name)} · ${m.role}">${esc((m.name||'?').slice(0,1).toUpperCase())}</span>`).join('');
  const link=_origin()+'#join/'+g.invite_code;
  return `<div class="dash-stack space-y-5">
    <div class="flex items-center gap-3"><button class="rcp-x" data-action="gBack" aria-label="Back">${ICON('x','ic-sm')}</button><h1 class="text-xl font-bold truncate">${g.emoji||'🎯'} ${esc(g.name)}</h1></div>
    <div class="glass-strong rounded-2xl p-6 text-center">
      ${ring(p,'complete',fmt(g.saved_amount))}
      <p class="mt-2 text-sm" ${M}>${fmt(g.saved_amount)} of <b style="color:var(--text)">${fmt(g.target_amount)}</b>${days!=null?` · ${days>0?days+' days left':'past due'}`:''}</p>
      <div class="mt-3 flex items-center justify-center">${avatars}${mem.length>6?`<span class="ml-2 text-xs" ${M}>+${mem.length-6}</span>`:''}<span class="ml-3 text-xs" ${M}>${mem.length} member${mem.length===1?'':'s'}</span></div>
    </div>
    ${canContribute?`<div class="glass rounded-2xl p-4"><label class="t-label">Add contribution</label>
      <div class="flex gap-2 mt-2"><input id="gAmt" class="input flex-1" inputmode="decimal" placeholder="Amount"><button class="btn btn-primary" data-action="gContribute" data-id="${g.id}">Add</button></div></div>`:
      `<div class="glass rounded-2xl p-4 text-sm" ${M}>You're a viewer in this group.</div>`}
    <div class="glass rounded-2xl p-4">
      <div class="flex items-center justify-between"><h3 class="font-bold">Activity</h3><span class="chip">${con.length}</span></div>
      ${con.length?`<div class="mt-2 space-y-2">${con.slice(0,20).map(c=>`<div class="flex items-center gap-3 py-1.5" style="border-bottom:1px solid var(--hair)"><span class="flex h-8 w-8 items-center justify-center rounded-full text-white text-xs font-bold" style="background:var(--card-2);color:var(--text)">${esc((c.name||'?').slice(0,1).toUpperCase())}</span><div class="min-w-0 flex-1"><p class="text-sm font-semibold truncate">${esc(c.name)} ${c.amount<0?'withdrew':'added'} ${fmt(Math.abs(c.amount))}</p>${c.note?`<p class="text-xs truncate" ${M}>${esc(c.note)}</p>`:''}</div><span class="text-xs" ${M}>${fmtAgo(c.created_at)}</span></div>`).join('')}</div>`:
        `<p class="mt-2 text-sm" ${M}>No contributions yet — be the first.</p>`}
    </div>
    <div class="glass rounded-2xl p-4">
      <div class="flex items-center justify-between"><h3 class="font-bold">Group chat</h3><span class="chip">50 msgs/day</span></div>
      <div id="gChatScroll" class="chat-scroll mt-2">${(g._msgs&&g._msgs.length)?g._msgs.map((m,i,a)=>{const grp=i>0&&a[i-1].name===m.name&&a[i-1].mine===m.mine;return `<div class="chat-row ${m.mine?'me':''} ${grp?'grp':''}"><div class="chat-bubble ${m.mine?'me':''}">${(m.mine||grp)?'':`<b class="chat-who">${esc(m.name||'Saver')}</b>`}${esc(m.body)}</div></div>`;}).join(''):`<div class="chat-empty">${ICON('users')}<p>No messages yet</p><span>Start the conversation with your group.</span></div>`}</div>
      ${(ME&&ME.plan!=='free')?`<div class="mt-3 flex gap-2"><input id="gChatInput" class="input flex-1" maxlength="500" placeholder="Message the group…"><button class="btn btn-primary" data-action="gSendText" data-id="${g.id}">Send</button></div>`
        :`<p class="t-label mt-3">Quick messages · upgrade to Pro for custom messages</p><div class="mt-1.5 flex flex-wrap gap-1.5">${chatPresets().map(t=>`<button class="btn btn-ghost btn-sm" data-action="gSendPreset" data-id="${g.id}" data-body="${esc(t)}">${esc(t)}</button>`).join('')}</div>`}
    </div>
    <div class="glass rounded-2xl p-4">
      <label class="t-label">Invite link</label>
      <div class="flex gap-2 mt-2"><input class="input flex-1" readonly value="${esc(link)}" onclick="this.select()"><button class="btn btn-ghost" data-action="gCopy" data-link="${esc(link)}">Copy</button></div>
      <p class="mt-2 text-xs" ${M}>Code: <b style="color:var(--text)">${esc(g.invite_code)}</b> · Privacy: ${g.privacy}</p>
    </div>
    ${g.role!=='owner'?`<button class="btn btn-ghost w-full" data-action="gLeave" data-id="${g.id}">Leave group</button>`:''}
  </div>`;
}

// ---- handlers ----
async function gCreate(name,emoji,target){
  const t=parseFloat(target)||0;if(!name||t<=0){toast('Enter a name and target','err');return;}
  if(DEMO_MODE){const g={id:'g'+Date.now(),owner_id:'demo',name,emoji:emoji||'🎯',target_amount:t,saved_amount:0,currency:'EUR',target_date:null,privacy:'invite',invite_code:Math.random().toString(36).slice(2,8),status:'active',role:'owner',_members:[{user_id:'demo',role:'owner',name:'You'}],_contribs:[]};GROUPS.unshift(g);GROUP_OPEN=g.id;render();toast('Group created');return;}
  try{const {data,error}=await sb.rpc('create_group_goal',{p_name:name,p_emoji:emoji||'🎯',p_target:t,p_currency:ME.currency||'EUR',p_target_date:null,p_privacy:'invite'});
    if(error)throw error;const g={...data,role:'owner',_members:[{user_id:SESSION.user.id,role:'owner',name:ME.first_name||'You'}],_contribs:[]};GROUPS.unshift(g);GROUP_OPEN=g.id;render();toast('Group created');
  }catch(e){toast('Could not create group','err');}
}
async function gJoinByCode(code){
  code=(code||'').trim();if(!code){toast('Enter a code','err');return;}
  if(DEMO_MODE){const g=GROUPS.find(x=>x.invite_code===code);if(g){GROUP_OPEN=g.id;render();toast('Joined!');}else toast('No group with that code (demo)','err');return;}
  try{const {data:gid,error}=await sb.rpc('join_group_by_code',{p_code:code});if(error)throw error;
    GROUPS_LOADED=false;await gEnsureLoaded();GROUP_OPEN=gid;render();toast('Joined group!');
  }catch(e){toast(e.message&&/invalid/i.test(e.message)?'Invalid or expired code':'Could not join','err');}
}
async function gContribute(gid,amount){
  const g=GROUPS.find(x=>x.id===gid);if(!g)return;const amt=parseFloat(amount)||0;if(amt===0){toast('Enter an amount','err');return;}
  const who=DEMO_MODE?'You':(ME.first_name||'You');
  const c={user_id:(uid&&uid())||'demo',name:who,amount:amt,note:'',created_at:new Date().toISOString()};
  g._contribs=g._contribs||[];g._contribs.unshift(c);g.saved_amount=Number(g.saved_amount)+amt;
  if(g.saved_amount>=g.target_amount)g.status='completed';
  render();
  if(DEMO_MODE)return;
  try{const {error}=await sb.from('group_contributions').insert({group_id:gid,user_id:SESSION.user.id,amount:amt});if(error)throw error;
    // reconcile authoritative saved_amount from the trigger
    const {data}=await sb.from('group_goals').select('saved_amount,status').eq('id',gid).single();
    if(data){g.saved_amount=Number(data.saved_amount);g.status=data.status;render();}
  }catch(e){g._contribs.shift();g.saved_amount=Number(g.saved_amount)-amt;toast('Could not add contribution','err');render();}
}
async function gLeave(gid){
  if(!confirm('Leave this group?'))return;
  if(!DEMO_MODE){try{await sb.from('group_members').delete().eq('group_id',gid).eq('user_id',SESSION.user.id);}catch(e){}}
  GROUPS=GROUPS.filter(x=>x.id!==gid);GROUP_OPEN=null;render();toast('Left group');
}


// ============================================================
// FRIENDS — follow + friend-requests + friends list (TikTok-style, finance-clean)
// Backend: follows / friend_requests / friendships + respond_friend_request/unfriend RPCs.
// Messaging is intentionally NOT here yet (separate build).
// ============================================================
let FRIENDS=[],FR_IN=[],FR_OUT=[],FRIENDS_LOADED=false,FCHAT=null,FCHAT_MSGS=[];
function chatPresets(){
  try{const s=snapshot(ME,EXPENSES);const g=topGoal();const st=(streakState().count)||0;
    return [
      'I saved '+fmt(Math.max(0,s.leftover))+' this month',
      g?('My "'+(g.name||'goal')+'" goal is '+pct(g.saved_amount,g.target_amount)+'% complete'):'I just set a new savings goal',
      st>0?("I'm on a "+st+'-day streak'):'I logged my spending today',
      'Just added money to my goal'
    ].map(x=>x.slice(0,180));
  }catch(e){return ['I saved money today','My goal is going well','I logged my spending','Just added to my goal'];}
}
let _fSearchT=null;

async function fEnsureLoaded(){
  if(FRIENDS_LOADED)return;
  FRIENDS_LOADED=true;
  if(DEMO_MODE){render();return;}
  try{const u=SESSION.user.id;
    const [{data:fr},{data:reqs}]=await Promise.all([
      sb.from('friendships').select('user_low,user_high').or(`user_low.eq.${u},user_high.eq.${u}`),
      sb.from('friend_requests').select('id,sender_id,receiver_id,status,created_at').or(`sender_id.eq.${u},receiver_id.eq.${u}`).eq('status','pending')
    ]);
    const ids=[...new Set((fr||[]).map(x=>x.user_low===u?x.user_high:x.user_low)
      .concat((reqs||[]).map(r=>r.sender_id===u?r.receiver_id:r.sender_id)))];
    let profs={};
    if(ids.length){const {data:p}=await sb.from('public_profiles').select('id,username,first_name,avatar_url,plan,level').in('id',ids);(p||[]).forEach(x=>profs[x.id]=x);}
    const nm=id=>{const p=profs[id];return p?{name:p.first_name||p.username||'Saver',un:p.username||'',plan:p.plan,lvl:p.level,av:p.avatar_url}:{name:'Saver',un:'',plan:'free',lvl:1};};
    FRIENDS=(fr||[]).map(x=>{const id=x.user_low===u?x.user_high:x.user_low;return {id,...nm(id)};});
    FR_IN=(reqs||[]).filter(r=>r.receiver_id===u).map(r=>({id:r.id,uid:r.sender_id,...nm(r.sender_id)}));
    FR_OUT=(reqs||[]).filter(r=>r.sender_id===u).map(r=>({id:r.id,uid:r.receiver_id,...nm(r.receiver_id)}));
  }catch(e){console.warn('[Goalify] friends load failed',e);}
  render();
}
function fAvatar(f,size){size=size||40;return `<span class="flex items-center justify-center overflow-hidden rounded-full text-white font-bold shrink-0" style="width:${size}px;height:${size}px;background:linear-gradient(135deg,var(--accent1),var(--accent2))">${f.av?`<img src="${esc(f.av)}" class="h-full w-full object-cover" alt="">`:esc((f.name||'?').slice(0,1).toUpperCase())}</span>`;}
function fRow(f,actions){const M='style="color:var(--muted)"';return `<div class="fr-row flex items-center gap-3 py-2.5 px-1 -mx-1 rounded-lg" style="border-bottom:1px solid var(--hair)">${fAvatar(f)}<div class="min-w-0 flex-1"><p class="truncate text-sm font-bold">${esc(f.name)} ${planBadge(f.plan)}</p><p class="truncate text-[11px]" ${M}>@${esc(f.un||(f.name||'').toLowerCase())}${f.lvl?' · Lv.'+f.lvl:''}</p></div>${actions}</div>`;}
function friendsView(){
  const M='style="color:var(--muted)"';
  const reqSection=(FR_IN.length||FR_OUT.length)?`<div class="glass rounded-2xl p-4">
    <h3 class="font-bold mb-1">Friend requests</h3>
    ${FR_IN.length?`<p class="t-label mt-2">Incoming</p>${FR_IN.map(f=>fRow(f,`<div class="flex gap-1.5"><button class="btn btn-primary btn-sm" data-action="fAccept" data-id="${f.id}">Accept</button><button class="btn btn-ghost btn-sm" data-action="fDecline" data-id="${f.id}">Decline</button></div>`)).join('')}`:''}
    ${FR_OUT.length?`<p class="t-label mt-3">Sent</p>${FR_OUT.map(f=>fRow(f,`<span class="chip">Pending</span>`)).join('')}`:''}
  </div>`:'';
  const friendsSection=`<div class="glass rounded-2xl p-4">
    <div class="flex items-center justify-between mb-1"><h3 class="font-bold">Friends</h3><span class="chip">${FRIENDS.length}</span></div>
    ${(!FRIENDS_LOADED&&!DEMO_MODE)?[0,1,2].map(()=>`<div class="flex items-center gap-3 py-2.5"><span class="sk" style="width:40px;height:40px;border-radius:9999px"></span><div class="flex-1"><span class="sk h-3 block" style="width:45%"></span><span class="sk h-2 block mt-1.5" style="width:30%"></span></div></div>`).join(''):FRIENDS.length?FRIENDS.map(f=>fRow(f,`<div class="flex gap-1.5"><button class="btn btn-primary btn-sm" data-action="fMsg" data-id="${f.id}" data-name="${esc(f.name)}">Message</button><button class="btn btn-ghost btn-sm" data-action="fUnfriend" data-id="${f.id}">Remove</button></div>`)).join('')
      :`<div class="empty-wrap mt-3 !py-8"><div class="empty-orb" style="height:3rem;width:3rem;margin:0 auto">${ICON('users')}</div><p class="mt-2 text-sm font-semibold">No friends yet</p><p class="mt-1 text-xs" ${M}>Search savers below and send a request.</p></div>`}
  </div>`;
  const chatPanel=FCHAT?`<div class="glass-strong rounded-2xl p-4">
    <div class="flex items-center justify-between"><h3 class="font-bold">Message ${esc(FCHAT.name)}</h3><button class="rcp-x" data-action="fMsgClose" aria-label="Close">${ICON('x','ic-sm')}</button></div>
    <div id="fChatScroll" class="chat-scroll mt-2">${FCHAT_MSGS.length?FCHAT_MSGS.map((m,i,a)=>{const grp=i>0&&a[i-1].mine===m.mine;return `<div class="chat-row ${m.mine?'me':''} ${grp?'grp':''}"><div class="chat-bubble ${m.mine?'me':''}">${esc(m.body)}<span class="chat-when">${fmtAgo(m.created_at)}</span></div></div>`;}).join(''):`<div class="chat-empty">${ICON('users')}<p>No messages yet</p><span>Say hi with a quick message below.</span></div>`}</div>
    <p class="t-label mt-3">Quick messages · 4 per day</p>
    <div class="mt-1.5 flex flex-wrap gap-1.5">${chatPresets().map(t=>`<button class="btn btn-ghost btn-sm" data-action="fSendPreset" data-body="${esc(t)}">${esc(t)}</button>`).join('')}</div>
  </div>`:'';
  return `<div class="dash-stack space-y-5">
    <div class="page-head"><div><h1 class="page-h1">Friends</h1><p class="page-sub">Follow savers, add friends, save together.</p></div>
      <button class="btn btn-primary shrink-0" data-action="gNew">${ICON('users','ic-sm')} Create Group Goal</button></div>
    ${chatPanel}
    <div class="glass rounded-2xl p-4"><label class="t-label">Find savers</label>
      <div class="so-search mt-2"><span class="so-ic">${ICON('search','ic-sm')}</span><input id="fSearch" class="input" placeholder="Search by name or username…" autocomplete="off"></div>
      <div id="fResults" class="mt-2"></div></div>
    ${reqSection}
    ${friendsSection}
  </div>`;
}
function fSearchInput(q){
  const box=document.getElementById('fResults');if(!box)return;
  if(!q||!q.trim()){box.innerHTML='';return;}
  clearTimeout(_fSearchT);
  _fSearchT=setTimeout(async()=>{
    let rows=[];
    if(!DEMO_MODE){try{const safe=q.trim().replace(/[%_,()]/g,'').slice(0,40);const u=SESSION.user.id;
      if(safe){const {data}=await sb.from('public_profiles').select('id,username,first_name,avatar_url,plan,level').or(`username.ilike.%${safe}%,first_name.ilike.%${safe}%`).neq('id',u).limit(8);rows=data||[];}
    }catch(e){}}
    const b=document.getElementById('fResults');if(!b)return;
    if((document.getElementById('fSearch')?.value||'').trim()!==q.trim())return;
    const friendIds=new Set(FRIENDS.map(f=>f.id)),outIds=new Set(FR_OUT.map(f=>f.uid));
    b.innerHTML=rows.length?rows.map(u=>{const f={id:u.id,name:u.first_name||u.username||'Saver',un:u.username,plan:u.plan,lvl:u.level,av:u.avatar_url};
      const act=friendIds.has(u.id)?`<span class="chip">Friends</span>`:outIds.has(u.id)?`<span class="chip">Requested</span>`:`<button class="btn btn-primary btn-sm" data-action="fAdd" data-id="${u.id}">Add</button>`;
      return fRow(f,act);}).join('')
      :`<p class="p-3 text-center text-sm" style="color:var(--muted)">${DEMO_MODE?'Member search activates once accounts go live.':'No savers found for “'+esc(q)+'”.'}</p>`;
  },350);
}
async function fAdd(id){
  if(DEMO_MODE){toast('Friend requests activate once accounts go live');return;}
  try{const {error}=await sb.from('friend_requests').insert({sender_id:SESSION.user.id,receiver_id:id,status:'pending'});
    if(error)throw error;toast('Friend request sent');FRIENDS_LOADED=false;await fEnsureLoaded();
  }catch(e){toast(/duplicate/i.test(e.message||'')?'Request already sent':'Could not send request','err');}
}
async function fRespond(rid,accept){
  if(DEMO_MODE)return;
  try{const {error}=await sb.rpc('respond_friend_request',{p_id:rid,p_accept:accept});if(error)throw error;
    toast(accept?'Friend added 🎉':'Request declined');FRIENDS_LOADED=false;await fEnsureLoaded();
  }catch(e){toast('Could not update request','err');}
}
async function fOpenChat(id,name){
  FCHAT={id,name};FCHAT_MSGS=[];render();
  if(DEMO_MODE)return;
  try{const u=SESSION.user.id;
    const {data}=await sb.from('friend_messages').select('sender_id,body,created_at')
      .or(`and(sender_id.eq.${u},receiver_id.eq.${id}),and(sender_id.eq.${id},receiver_id.eq.${u})`)
      .order('created_at',{ascending:true}).limit(30);
    FCHAT_MSGS=(data||[]).map(m=>({body:m.body,created_at:m.created_at,mine:m.sender_id===u}));render();
  }catch(e){}
}
async function fSendPreset(body){
  if(!FCHAT)return;
  const mine={body,created_at:new Date().toISOString(),mine:true};
  if(DEMO_MODE){FCHAT_MSGS.push(mine);render();return;}
  FCHAT_MSGS.push(mine);render();
  const {error}=await sb.rpc('send_friend_message',{p_to:FCHAT.id,p_body:body});
  if(error){FCHAT_MSGS.pop();render();toast(/LIMIT/.test(error.message)?'Daily limit reached — 4 quick messages per day':'Could not send','err');}
}
async function fUnfriend(id){
  if(!confirm('Remove this friend?'))return;
  if(!DEMO_MODE){try{await sb.rpc('unfriend',{p_other:id});}catch(e){}}
  FRIENDS=FRIENDS.filter(f=>f.id!==id);render();toast('Friend removed');
}
